// Ordered keyword rules — first match wins. ItemIds are engine-defined and
// open-ended (herb_blueleaf, yew_longbow, map_fragment.iron_coast, ...), so we
// match on name fragments rather than maintaining a per-item table. Weapon and
// armor words go first so e.g. herbalist_gloves resolves to gloves, not herb.
const RULES: Array<[RegExp, IconName]> = [
  [/dagger|knife/, 'dagger'],
  [/bow/, 'bow'],
  [/cudgel|club|mace|hammer/, 'club'],
  [/staff|spear|polearm/, 'staff'],
  [/wand/, 'wand'],
  [/axe/, 'axe'],
  [/sword|blade|sabre|saber/, 'sword'],
  [/shield|buckler/, 'shield'],
  [/circlet|crown|tiara|diadem/, 'circlet'],
  [/hood|cowl/, 'hood'],
  [/helm/, 'helm'],
  [/cuirass|breastplate|plate|mail/, 'breastplate'],
  [/coat|jerkin|vest|tunic|robe|shirt|garb/, 'vest'],
  [/trouser|breeches|pants|legging/, 'trousers'],
  [/boot|shoe|sandal/, 'boots'],
  [/glove|gauntlet|mitt/, 'gloves'],
  [/amulet|pendant|necklace|sigil|talisman|charm/, 'pendant'],
  [/bracelet|bracer|band|loop|cuff/, 'bracer'],
  [/ring/, 'ring'],
  [/book|tome|grimoire/, 'book'],
  [/herb|leaf|flower|sprig/, 'herb'],
  [/ore|ingot|mineral|crystal|gem/, 'ore'],
  [/parchment|scroll|paper|letter/, 'scroll'],
  [/map/, 'map'],
  [/bread|ration|food|meal|stew|jerky/, 'bread'],
  [/arrow|bolt|quiver/, 'arrow'],
  [/pelt|hide|fur|leather/, 'hide'],
  [/key/, 'key'],
];

export function iconForItem(itemId: string, category?: ItemCategory): IconName {
  const id = itemId.toLowerCase();
  for (const [re, name] of RULES) {
    if (re.test(id)) return name;
  }
  if (category === 'KEY') return 'key';
  return 'sack';
}

interface Props {
  itemId: string;
  category?: ItemCategory;
  /** Pixel size; the glyph is square. Defaults to 20. */
  size?: number;
  className?: string;
}

// One item glyph, colored via currentColor (rarity classes set `color`).
export function ItemIcon({ itemId, category, size = 20, className }: Props) {
  const name = iconForItem(itemId, category);
  return (
    <svg
      viewBox="0 0 512 512"
      width={size}
      height={size}
      className={className}
      aria-hidden="true"
      focusable="false"
    >
      <path d={ICON_PATHS[name]} fill="currentColor" />
    </svg>
  );
}
